# Problem 2
def to_min(t):
    h, m = map(int, t.split(':'))
    return h * 60 + m

def to_str(m):
    return f"{m//60:02d}:{m%60:02d}"

work_start, work_end = 540, 1020
duration = 30

busy = {
    'Jeffrey': [],
    'Harold': {
        'Monday': [(to_min('09:00'), to_min('10:00')),
                   (to_min('10:30'), to_min('17:00'))],
        'Tuesday': [(to_min('09:00'), to_min('09:30')),
                    (to_min('10:30'), to_min('11:30')),
                    (to_min('12:30'), to_min('13:30')),
                    (to_min('14:30'), to_min('15:30')),
                    (to_min('16:00'), to_min('17:00'))],
    }
}

def complement(intervals):
    free = []
    cur = work_start
    for s, e in sorted(intervals):
        if cur < s:
            free.append((cur, s))
        cur = max(cur, e)
    if cur < work_end:
        free.append((cur, work_end))
    return free

def intersect(a, b):
    i, j = 0, 0
    res = []
    while i < len(a) and j < len(b):
        s = max(a[i][0], b[j][0])
        e = min(a[i][1], b[j][1])
        if s < e:
            res.append((s, e))
        if a[i][1] < b[j][1]:
            i += 1
        else:
            j += 1
    return res

days = ['Monday', 'Tuesday']
solution = None

# Preference: avoid Monday if possible, avoid Tuesday before 14:30
for day in days:
    harold_busy = busy['Harold'][day]
    harold_free = complement(harold_busy)
    # Jeffrey is always free
    common = harold_free
    for s, e in common:
        if day == 'Tuesday' and s < to_min('14:30'):
            s = to_min('14:30')
        if s + duration <= e:
            solution = (day, s, s + duration)
            break
    if solution:
        # if we found a slot on Tuesday (preferred) break, else keep Monday slot only if no Tuesday slot
        if day == 'Tuesday':
            break

day, start, end = solution
print([day, to_str(start), to_str(end)])

