# Problem 1
from datetime import datetime, timedelta

def to_min(t):
    h, m = map(int, t.split(':'))
    return h * 60 + m

def to_str(m):
    h = m // 60
    mi = m % 60
    return f"{h:02d}:{mi:02d}"

work_start = to_min('09:00')
work_end = to_min('17:00')
duration = 30

days = ['Monday', 'Tuesday', 'Wednesday', 'Thursday']

# busy intervals per person per day (in minutes)
ruth_busy = {
    'Monday': [('09:00', '17:00')],
    'Tuesday': [('09:00', '17:00')],
    'Wednesday': [('09:00', '17:00')],
    'Thursday': [('09:00', '11:00'), ('11:30', '14:30'), ('15:00', '17:00')],
}
# Julie has no meetings
julie_busy = {d: [] for d in days}

def intervals_to_minutes(lst):
    return [(to_min(s), to_min(e)) for s, e in lst]

def is_free(start, end, busy):
    for b_start, b_end in busy:
        if start < b_end and end > b_start:
            return False
    return True

for day in days:
    ruth_int = intervals_to_minutes(ruth_busy.get(day, []))
    julie_int = intervals_to_minutes(julie_busy.get(day, []))
    # preference: Julie avoid before 11:30 on Thursday
    pref_ok = True
    if day == 'Thursday':
        if start := None:  # placeholder to avoid lint errors
            pass
    for start in range(work_start, work_end - duration + 1):
        end = start + duration
        if not is_free(start, end, ruth_int):
            continue
        if not is_free(start, end, julie_int):
            continue
        if day == 'Thursday' and start < to_min('11:30'):
            continue
        print([day, to_str(start), to_str(end)])
        raise SystemExit

