import sys

WORK_START = 9 * 60
WORK_END = 17 * 60
DURATION = 60  # minutes

def to_min(t):
    h, m = map(int, t.split(":"))
    return h * 60 + m

def fmt(m):
    return f"{m // 60:02d}:{m % 60:02d}"

def complement(busy):
    free = []
    cur = WORK_START
    for s, e in sorted(busy):
        if s > cur:
            free.append((cur, s))
        cur = max(cur, e)
    if cur < WORK_END:
        free.append((cur, WORK_END))
    return free

def intersect(a, b):
    i = j = 0
    res = []
    while i < len(a) and j < len(b):
        s1, e1 = a[i]
        s2, e2 = b[j]
        s = max(s1, s2)
        e = min(e1, e2)
        if s < e:
            res.append((s, e))
        if e1 <= e2:
            i += 1
        else:
            j += 1
    return res

# Busy intervals per day
busy = {
    "Monday": {
        "Russell": [(to_min("10:30"), to_min("11:00"))],
        "Alexander": [(to_min("9:00"), to_min("11:30")), (to_min("12:00"), to_min("14:30")),
                      (to_min("15:00"), to_min("17:00"))],
    },
    "Tuesday": {
        "Russell": [(to_min("13:00"), to_min("13:30"))],
        "Alexander": [(to_min("9:00"), to_min("10:00")), (to_min("13:00"), to_min("14:00")),
                      (to_min("15:00"), to_min("15:30")), (to_min("16:00"), to_min("16:30"))],
    },
}

days = ["Monday", "Tuesday"]
for day in days:
    # Build free intervals for each participant
    free_lists = []
    for person in busy[day]:
        free_lists.append(complement(busy[day][person]))
    # Intersect all participants
    common = free_lists[0]
    for fl in free_lists[1:]:
        common = intersect(common, fl)
    # Apply Russell's preference on Tuesday
    if day == "Tuesday":
        pref_start = to_min("13:30")
        # Trim intervals to start no earlier than 13:30
        trimmed = []
        for s, e in common:
            if e <= pref_start:
                continue
            trimmed.append((max(s, pref_start), e))
        common = trimmed
    # Find a slot
    for s, e in common:
        if e - s >= DURATION:
            start = s
            end = s + DURATION
            print([day, fmt(start), fmt(end)])
            sys.exit(0)

