        'Monday':    [('9:30','10:00'),('10:30','11:00'),('11:30','12:00'),('14:00','14:30')],
        'Tuesday':   [('12:00','13:00')],
        'Wednesday': [('9:00','10:00'),('13:00','14:00')],
    },
    'Betty': {
        'Monday':    [('9:00','10:00'),('11:00','11:30'),('14:30','15:00'),('15:30','16:00')],
        'Tuesday':   [('9:00','9:30'),('11:30','12:00'),('12:30','14:30'),('15:30','16:00')],
        'Wednesday': [('10:00','11:30'),('12:00','14:00'),('14:30','17:00')],
    },
}

work_start = to_min('9:00')
work_end   = to_min('17:00')
duration   = 60

days_preference = ['Tuesday', 'Wednesday', 'Monday']  # avoid Monday if possible

answer = None
for day in days_preference:
    intervals = []
    for person in busy:
        for s, e in busy[person].get(day, []):
            intervals.append([to_min(s), to_min(e)])
    merged_busy = merge(intervals)

    free = []
    cur = work_start
    for s, e in merged_busy:
        if cur < s:
            free.append([cur, s])
        cur = max(cur, e)
    if cur < work_end:
        free.append([cur, work_end])

    # apply Betty's Tuesday constraint (cannot meet after 12:30)
    for s, e in free:
        if e - s >= duration:
            if day == 'Tuesday' and s + duration > to_min('12:30'):
                # meeting would finish after 12:30, not allowed
                continue
            answer = [day, to_str(s), to_str(s + duration)]
            break
    if answer:
        break

print(answer)

# Problem 4
def to_min(t):
    h, m = map(int, t.split(':'))
    return h * 60 + m

def to_str(m):
    return f"{m // 60:02d}:{m % 60:02d}"

def merge(intervals):
    intervals.sort()
    merged = []
    for s, e in intervals:
        if not merged or s > merged[-1][1]:
            merged.append([s, e])
        else:
            merged[-1][1] = max(merged[-1][1], e)
    return merged

