# Problem 5
def to_min(t):
    h, m = map(int, t.split(':'))
    return h * 60 + m

def to_str(m):
    return f"{m // 60:02d}:{m % 60:02d}"

def merge(intervals):
    intervals.sort()
    merged = []
    for s, e in intervals:
        if not merged or s > merged[-1][1]:
            merged.append([s, e])
        else:
            merged[-1][1] = max(merged[-1][1], e)
    return merged

busy = {
    'Shirley':  [('10:30','11:00'),('12:00','12:30')],
    'Jacob':    [('9:00','9:30'),('10:00','10:30'),('11:00','11:30'),('12:30','13:30'),('14:30','15:00')],
    'Stephen':  [('11:30','12:00'),('12:30','13:00')],
    'Margaret': [('9:00','9:30'),('10:30','12:30'),('13:00','13:30'),('15:00','15:30'),('16:30','17:00')],
    'Mason':    [('9:00','10:00'),('10:30','11:00'),('11:30','12:30'),('13:00','13:30'),('14:00','14:30'),('16:30','17:00')],
}

work_start = to_min('9:00')
work_end   = to_min('17:00')
duration   = 30
earliest_allowed = to_min('14:30')   # Margaret's preference

intervals = []
for person in busy:
    for s, e in busy[person]:
        intervals.append([to_min(s), to_min(e)])

merged_busy = merge(intervals)

free = []
cur = work_start
for s, e in merged_busy:
    if cur < s:
        free.append([cur, s])
    cur = max(cur, e)
if cur < work_end:
    free.append([cur, work_end])

answer = None
for s, e in free:
    if s < earliest_allowed:
        s = earliest_allowed
    if e - s >= duration:
        answer = ['Monday', to_str(s), to_str(s + duration)]
        break

print(answer)
